import React, { useState, useEffect } from "react";
import "./AdminDashboard.css";

export default function AdminDashboard() {
  const [selectedBranch, setSelectedBranch] = useState(null);
  const [branchAttendance, setBranchAttendance] = useState([]);
  const [loading, setLoading] = useState(false);

  const branches = ["Hitech City", "Vanasthalipuram", "Nagole"];

  useEffect(() => {
    if (localStorage.getItem("role") !== "admin") {
      window.location.href = "/login";
    }
  }, []);

  const fetchBranchAttendance = async (branch) => {
    setLoading(true);
    setSelectedBranch(branch);
    try {
      const res = await fetch(`http://localhost:5000/api/attendance/branch/${encodeURIComponent(branch)}`);
      if (!res.ok) throw new Error("Failed to fetch attendance");
      const data = await res.json();
      setBranchAttendance(data);
    } catch (err) {
      alert("Failed to load branch attendance");
      console.error(err);
      setBranchAttendance([]);
    } finally {
      setLoading(false);
    }
  };

  

const viewFullAttendance = (employee) => {
  const params = new URLSearchParams({
    userId: employee.userId,
    name: employee.name,
    designation: employee.designation || "N/A",
    branch: selectedBranch
  });

  window.location.href = `/attendance-details?${params.toString()}`;
};



  const handleLogout = () => {
    localStorage.clear();
    window.location.href = "/login";
  };

  return (
    <div className="admin-dashboard">
      <div className="admin-header">
        <h1>Admin Dashboard - Attendance Overview</h1>
        <button className="logout-btn" onClick={handleLogout}>Logout</button>
      </div>

      {/* Branch Cards */}
      <div className="branches-grid">
        {branches.map((branch) => (
          <div
            key={branch}
            className={`branch-card ${selectedBranch === branch ? "active" : ""}`}
            onClick={() => fetchBranchAttendance(branch)}
          >
            <h3>{branch}</h3>
            <p>Click to view today's attendance</p>
          </div>
        ))}
      </div>

      {/* Branch Attendance Table */}
      {selectedBranch && (
        <div className="attendance-section">
          <h2>Today's Attendance - {selectedBranch}</h2>
          <p><strong>Date:</strong> {new Date().toLocaleDateString()}</p>

          {loading ? (
            <p>Loading attendance data...</p>
          ) : branchAttendance.length === 0 ? (
            <p>No employees or attendance data for this branch today.</p>
          ) : (
            <table className="branch-attendance-table">
              <thead>
                <tr>
                  <th>Name</th>
                  <th>ID</th>
                  <th>Designation</th>
                  <th>Status</th>
                  <th>Check In</th>
                  <th>Check Out</th>
                  <th>Hours</th>
                  <th>Action</th>
                </tr>
              </thead>
              <tbody>
                {branchAttendance.map((emp) => (
                  <tr key={emp.userId} className={emp.status === "Absent" ? "absent-row" : ""}>
                    <td>{emp.name}</td>
                    <td>{emp.userId}</td>
                    <td>{emp.designation}</td>
                    <td>
                      <span className={`status-badge status-${emp.status.toLowerCase().replace(" ", "-")}`}>
                        {emp.status}
                      </span>
                    </td>
                    <td>{emp.checkIn}</td>
                    <td>{emp.checkOut}</td>
                    <td>{emp.hours}</td>
                    <td>
                      <button
                        className="view-full-btn"
                        onClick={() => viewFullAttendance(emp)}
                      >
                        Full History
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}
    </div>
  );
}
